 internal static async Task<CanvasDocument> PhotoDocument(Guid project,string root){var doc=new CanvasDocument{SchemaVersion=2,ProjectId=project,PixelWidth=1920,PixelHeight=1080,Name="摄影大图 · 固定版本"};var list=new List<CanvasObject>();foreach(var path in Inputs()){var item=await CanvasPixelRenderer.ImportAsync(path,doc,root);list.Add(item with{X=40+list.Count*520,Y=80+list.Count*80,Width=700,Height=650,Rotation=list.Count*11,FlipX=list.Count==1,Opacity=.78,CropRect=new(.1,.1,.8,.8)});}list.Add(new(){CanvasId=doc.CanvasId,Text="摄影照片预览",Name="标题 · 摄影照片预览",X=100,Y=10,Width=900,Height=70,FontSize=48});list.Add(new(){CanvasId=doc.CanvasId,Name="软画笔",Width=1920,Height=1080,SourceWidth=1920,SourceHeight=1080,BrushStrokes=[new([new(.1,.8),new(.8,.9)],"#7AC345",22,.5,.3)]});return doc with{Objects=list.ToArray()};}
 [TestMethod]public Task AuthorizedLargePhotoCaptureMeasuresColdRepeatAndRelease()=>RunSta(async()=>{
  EnsureTestApplication();Directory.CreateDirectory(Root);using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);var doc=new CanvasDocument{ProjectId=f.Id,PixelWidth=1920,PixelHeight=1080};var store=new CanvasDocumentStore(Path.Combine(f.Root,"canvas"));var paths=Inputs();var items=new List<CanvasObject>();var rows=new List<object>();foreach(var path in paths){var image=await CanvasPixelRenderer.ImportAsync(path,doc,store.DirectoryPath);items.Add(image with{X=40+items.Count*400,Y=60+items.Count*70,Width=650,Height=440,Opacity=.7,Rotation=items.Count*13,FlipX=items.Count%2==0,CropRect=new(.1,.1,.8,.8)});}doc=doc with{Objects=items.Concat(items.Take(2).Select((x,n)=>x with{ObjectId=Guid.NewGuid(),X=150+n*700,Y=480,ZIndex=10+n})).ToArray()};await store.SaveAsync(doc);await f.Vm.LoadAsync(f.Id);long baseWs=0,peakWs=0,basePrivate=0,peakPrivate=0;using(var p=Process.GetCurrentProcess()){baseWs=peakWs=p.WorkingSet64;basePrivate=peakPrivate=p.PrivateMemorySize64;}using var sample=new CancellationTokenSource();var sampling=Task.Run(async()=>{while(!sample.IsCancellationRequested){using var p=Process.GetCurrentProcess();peakWs=Math.Max(peakWs,p.WorkingSet64);peakPrivate=Math.Max(peakPrivate,p.PrivateMemorySize64);try{await Task.Delay(5,sample.Token);}catch(OperationCanceledException){}}});var watch=Stopwatch.StartNew();string? error=null;try{await f.Vm.CaptureCanvasDocumentAsync(doc);}catch(Exception e){error=e.GetType().Name+": "+e.Message;}var elapsed=watch.Elapsed.TotalMilliseconds;sample.Cancel();await sampling;File.WriteAllText(Path.Combine(Root,"LARGE_PHOTO_MEASUREMENT.json"),JsonSerializer.Serialize(new{error,elapsedMs=elapsed,baseWs,peakWs,wsDelta=peakWs-baseWs,basePrivate,peakPrivate,privateDelta=peakPrivate-basePrivate,snapshots=f.Vm.DocumentCanvasRevisions.Count,input=paths,scope="authorized photographic derivatives, no private pixels in Git; 5ms process sample; work budget != whole process cap"},new JsonSerializerOptions{WriteIndented=true}));Assert.IsNull(error,"Ordinary 24/33MP JPEG must capture under work budget");Assert.AreEqual(1,f.Vm.DocumentCanvasRevisions.Count);var first=f.Vm.DocumentCanvasRevisions[0].PreviewPngBase64;var repeats=new List<object>();for(int n=0;n<3;n++){watch.Restart();await f.Vm.CaptureCanvasDocumentAsync(doc);using var process=Process.GetCurrentProcess();repeats.Add(new{n,elapsedMs=watch.Elapsed.TotalMilliseconds,ws=process.WorkingSet64,privateBytes=process.PrivateMemorySize64,managedBytes=GC.GetTotalMemory(false)});}Assert.AreEqual(first,f.Vm.DocumentCanvasRevisions[0].PreviewPngBase64);Assert.AreEqual(4,f.Vm.DocumentCanvasRevisions.Count);Assert.IsTrue(await f.Vm.FlushAsync());var other=f.NewVm();await other.LoadAsync(f.Id);Assert.AreEqual(first,other.DocumentCanvasRevisions[0].PreviewPngBase64);Assert.AreEqual(4,other.DocumentCanvasRevisions.Count);File.WriteAllText(Path.Combine(Root,"REPEAT_RESOURCE_LOCAL.json"),JsonSerializer.Serialize(new{repeats,retainedSnapshotCount=4,taskCacheRetainedBytes=0,scope="after completion process memory includes saved PNG versions, CLR and WIC; not all memory is cache"},new JsonSerializerOptions{WriteIndented=true}));
 });
 [TestMethod]public Task NativeJpegProxyIdentityCacheAndNumericalFixtures()=>RunSta(async()=>{
  EnsureTestApplication();Directory.CreateDirectory(Root);using(var profile=new ColorContext(PixelFormats.Bgra32).OpenProfileStream())using(var dest=File.Create(Path.Combine(Root,"wic-target-profile.icc")))profile.CopyTo(dest);var paths=Inputs();var doc=new CanvasDocument{PixelWidth=1920,PixelHeight=1080};var items=new List<CanvasObject>();foreach(var path in paths){var item=await CanvasPixelRenderer.ImportAsync(path,doc,Path.Combine(Root,"fixture-canvas"));items.Add(item with{X=50,Y=80,Width=800,Height=600});}doc=doc with{Objects=[items[0],items[1],items[2],items[0] with{ObjectId=Guid.NewGuid(),X=900},items[1] with{ObjectId=Guid.NewGuid(),Y=500}]};var frozen=CanvasPixelRenderer.FreezeSnapshotSources(doc);var preview=CanvasPixelRenderer.RenderPhotoPreview(frozen,out var metrics);Assert.AreEqual(3,metrics.SourceDecodes);Assert.AreEqual(2,metrics.CacheHits);Assert.IsTrue(metrics.PeakCacheBytes<=32L*1024*1024);Assert.AreEqual(0,metrics.RetainedCacheBytes);File.WriteAllText(Path.Combine(Root,"CACHE_METRICS.json"),JsonSerializer.Serialize(metrics,new JsonSerializerOptions{WriteIndented=true}));
  foreach(var item in items.Take(2)){using var stream=CanvasPixelRenderer.OpenSource(item,CancellationToken.None);var header=BitmapDecoder.Create(stream,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnDemand).Frames[0];var image=CanvasJpegNativePreview.Read(stream,header.PixelWidth,header.PixelHeight,200L*1024*1024,CancellationToken.None,out var w,out var h);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));var name=Path.GetFileNameWithoutExtension(item.Name);using(var f=File.Create(Path.Combine(Root,name+"-native-local-only.png")))encoder.Save(f);using var session=new CanvasPhotoPreviewSession();var data=session.Read(item,1400,788,new(),CancellationToken.None);
   // Existing WIC color/orientation contract on the EXACT native sample; independent LCMS differences are not hidden.
   stream.Position=0;var sourceFrame=BitmapDecoder.Create(stream,BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnDemand).Frames[0];var meta=new BitmapMetadata("tiff");if(sourceFrame.Metadata is BitmapMetadata sourceMeta){foreach(var query in new[]{"/app1/ifd/{ushort=274}","/ifd/{ushort=274}"})try{if(sourceMeta.GetQuery(query) is ushort o)meta.SetQuery("/ifd/{ushort=274}",o);}catch(NotSupportedException){}}var tiff=new TiffBitmapEncoder();tiff.Frames.Add(BitmapFrame.Create(image,null,meta,new System.Collections.ObjectModel.ReadOnlyCollection<ColorContext>((sourceFrame.ColorContexts??new System.Collections.ObjectModel.ReadOnlyCollection<ColorContext>([])).ToArray())));var nativeFile=Path.Combine(Root,Path.GetFileNameWithoutExtension(item.Name)+"-native-icc-local-only.tif");using(var dst=File.Create(nativeFile))tiff.Save(dst);var legacy=CanvasPixelRenderer.ReadSource(item with{PlanningSource=null,SourcePath=nativeFile,ContentHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(nativeFile)))});CollectionAssert.AreEqual(PlanningCanvasConsistencyTests.Pixels(legacy),data.Pixels,"ICC and orientation must retain the existing exact WIC contract");File.WriteAllBytes(Path.Combine(Root,name+"-oriented-local-only.bgra"),data.Pixels);File.WriteAllText(Path.Combine(Root,name+"-proxy.json"),JsonSerializer.Serialize(new{source=Path.GetFileName(item.Name),nativeWidth=w,nativeHeight=h,orientedWidth=data.Width,orientedHeight=data.Height,profileCount=header.ColorContexts?.Count??0,contract="native GetClosestSize(request longest1024) then ICC→sRGB then EXIF; straight BGRA; no cached thumbnail"}));}
  await Task.CompletedTask;
 });
