 [TestMethod]public Task LargePhotoSamplingCropAlphaAndRowBoundariesMatchFrozenProxyOracle()=>RunSta(async()=>{
  EnsureTestApplication();Directory.CreateDirectory(Root);var doc=new CanvasDocument{PixelWidth=1920,PixelHeight=1080};var list=new List<CanvasObject>();foreach(var path in Inputs()){var item=await CanvasPixelRenderer.ImportAsync(path,doc,Path.Combine(Root,"oracle-canvas"));list.Add(item with{Width=950,Height=800,X=-70+list.Count*430,Y=20+list.Count*80,Opacity=.63,Rotation=13,FlipX=true,CropRect=new(.17,.22,.61,.57),ZIndex=list.Count});}doc=doc with{Objects=list.ToArray()};var actual=CanvasPixelRenderer.RenderPhotoPreview(doc,out var metrics);var root=Path.Combine(Root,"proxy-oracle-local-only");Directory.CreateDirectory(root);var layers=new List<object>();var proxies=new List<CanvasObject>();using(var session=new CanvasPhotoPreviewSession()){int n=0;foreach(var item in list){var raster=session.Read(item,1400,788,new(),CancellationToken.None);var bitmap=BitmapSource.Create(raster.Width,raster.Height,96,96,PixelFormats.Bgra32,null,raster.Pixels,raster.Width*4);var output=Path.Combine(root,$"proxy-{n}.png");var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(output))e.Save(f);var raw=$"proxy-{n}.bgra";File.WriteAllBytes(Path.Combine(root,raw),raster.Pixels);layers.Add(new{file=raw,width=raster.Width,height=raster.Height,item});proxies.Add(item with{PlanningSource=null,SourcePath=output,ContentHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(output)))});n++;}}
  var reference=CanvasPixelRenderer.RenderPreview(doc with{Objects=proxies.ToArray()});CollectionAssert.AreEqual(PlanningCanvasConsistencyTests.Pixels(reference),PlanningCanvasConsistencyTests.Pixels(actual));var bytes=PlanningCanvasConsistencyTests.Pixels(actual);File.WriteAllBytes(Path.Combine(root,"product.bgra"),bytes);File.WriteAllText(Path.Combine(root,"INPUT.json"),JsonSerializer.Serialize(new{artboardWidth=doc.PixelWidth,artboardHeight=doc.PixelHeight,width=actual.PixelWidth,height=actual.PixelHeight,layers,metrics},new JsonSerializerOptions{WriteIndented=true}));Assert.IsTrue(bytes.Where((_,i)=>i%4==3).Any(a=>a==0));Assert.IsTrue(bytes.Where((_,i)=>i%4==3).Any(a=>a>0&&a<255));
 });

