 [TestMethod]public Task V3ActualCancellationAndSourceRevalidationRetireTaskCache()=>RunSta(async()=>{
  EnsureTestApplication();Directory.CreateDirectory(Root);var doc=new CanvasDocument();var item=await CanvasPixelRenderer.ImportAsync(Inputs()[0],doc,Path.Combine(Root,"cancel-canvas"));doc=doc with{Objects=Enumerable.Range(0,15).Select(n=>item with{ObjectId=Guid.NewGuid(),X=n*30,Y=n*10}).ToArray()};using var c=new CancellationTokenSource();var clock=Stopwatch.StartNew();var work=PlanningCanvasSnapshot.RenderAsync(doc,c.Token);await Task.Delay(10);var requested=clock.Elapsed.TotalMilliseconds;c.Cancel();await Assert.ThrowsAsync<OperationCanceledException>(()=>work);var retired=clock.Elapsed.TotalMilliseconds;var next=CanvasPixelRenderer.RenderPhotoPreview(doc,out var metrics);Assert.AreEqual(0,metrics.RetainedCacheBytes);Assert.AreEqual(1,metrics.SourceDecodes);Assert.AreEqual(14,metrics.CacheHits);var path=RAWSelectionAssistant.Core.Services.Projects.PlanningProjectCopyStorage.Resolve(item.PlanningSource!.Bind());using var session=new CanvasPhotoPreviewSession();session.Read(item,1400,788,new(),CancellationToken.None);var source=File.ReadAllBytes(path);File.WriteAllBytes(path,source.Concat(new byte[]{9}).ToArray());try{Assert.ThrowsExactly<InvalidDataException>(()=>session.Read(item,1400,788,new(),CancellationToken.None));}finally{File.WriteAllBytes(path,source);}File.WriteAllText(Path.Combine(Root,"CANCEL_AND_REVALIDATE.json"),JsonSerializer.Serialize(new{requestMs=requested,retirementMs=retired,metrics,scope="request posted while actual worker active; WIC substage unknown, no native preemption claim"},new JsonSerializerOptions{WriteIndented=true}));
 });
